import json
import os

VIEWER = 'Viewer'
SUPER_ADMIN = 'SuperAdmin'
_ROLES = {}


def app_admin_emails():
    value = json.loads(os.environ['STACKVEND_APP_ADMIN_EMAILS'])
    if not isinstance(value, list) or not all(isinstance(e, str) for e in value):
        raise RuntimeError('STACKVEND_APP_ADMIN_EMAILS is not a JSON list of strings')
    return value


def get_role(email):
    if email.lower() in app_admin_emails():
        return SUPER_ADMIN
    return _ROLES.get(email.lower(), VIEWER)
